use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentitySubjectVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Create\UserFederatedIdentityCreateParams;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Create\UserFederatedIdentityCreateResult;

class UserFederatedIdentityCreateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly UserFederatedIdentityCreateUsecase $createUsecase,
    ) {
    }
    #[OA\Post(
        path: "/api/access/user-federated-identities",
        tags: ["User federated identity"],
        description:"Create",
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserFederatedIdentityApiDTO")),
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserFederatedIdentityApiDTO")),
              new OA\Response(response: 422, description: "Constraint error"),
          ]
    )]
    public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Create User federated identity");
        $span = $this->startSpan("Create User federated identity");
        $this->sql->begin();
        try {
            $value = $this->readUserFederatedIdentity($request);
            $result = $this->createUsecase->create($value);
            $this->sql->commit();
            $value = $this->mapUserFederatedIdentity($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readUserFederatedIdentity(ServerRequestInterface $request): UserFederatedIdentityCreateParams
    {
        $this->logDebug("Read entity for User federated identity");
        $span = $this->startSpan("Read entity for User federated identity");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new UserFederatedIdentityCreateParams();
            $valueUid = UserFederatedIdentityUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('user', array_keys($body))) {
                $valueUser = UserFederatedIdentityUserVO::tryFrom(isset($body['user']['$ref']) ? new UserRef($body['user']['$ref']) : null, $errorsList);
                if (null !== $valueUser) {
                    $value->user($valueUser);
                }
            }
            if (in_array('loginProvider', array_keys($body))) {
                $valueLoginProvider = UserFederatedIdentityLoginProviderVO::tryFrom(isset($body['loginProvider']['$ref']) ? new TenantLoginProviderRef($body['loginProvider']['$ref']) : null, $errorsList);
                if (null !== $valueLoginProvider) {
                    $value->loginProvider($valueLoginProvider);
                }
            }
            $valueSubject = UserFederatedIdentitySubjectVO::tryFrom($body['subject'] ?? null, $errorsList);
            if (null !== $valueSubject) {
                $value->subject($valueSubject);
            }
            $value->version(UserFederatedIdentityVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapUserFederatedIdentity(ServerRequestInterface $request, UserFederatedIdentityCreateResult $value): UserFederatedIdentityApiDTO
    {
        $this->logDebug("Map entity to output dto for User federated identity");
        $span = $this->startSpan("Map entity to output dto for User federated identity");
        try {
            $user = $value->getUser();
            $loginProvider = $value->getLoginProvider();
            $dto = new UserFederatedIdentityApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->loginProvider = $loginProvider ? ['$ref' => $loginProvider->uid()] : null;
            $dto->subject = $value->getSubject();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
